   920→    const next    = current === 'dark' ? 'light' : 'dark';
   921→    document.documentElement.setAttribute('data-theme', next);
   922→    localStorage.setItem('theme', next);
   923→    updateDarkIcon(next);
   924→}
   925→
   926→function updateDarkIcon(theme) {
   927→    const icon = document.getElementById('darkIcon');
   928→    if (!icon) return;
   929→    icon.className = theme === 'dark' ? 'bi bi-sun' : 'bi bi-moon';
   930→}
   931→
   932→// ---- INTERSECTION OBSERVER (fade-up) ----
   933→document.addEventListener('DOMContentLoaded', function() {
   934→    const io = new IntersectionObserver(entries => {
   935→        entries.forEach(entry => {
   936→            if (entry.isIntersecting) {
   937→                entry.target.classList.add('in-view');
   938→                io.unobserve(entry.target);
   939→            }
   940→        });
   941→    }, { threshold: 0.1 });
   942→    document.querySelectorAll('.fade-up').forEach(el => io.observe(el));
   943→});
   944→
   945→// ---- CLOSE SIDEBAR ON ESC ----
   946→document.addEventListener('keydown', e => {
   947→    if (e.key === 'Escape') closeSidebar();
   948→});
   949→
   950→// ---- NAV PROGRESS BAR ----
   951→(function() {
   952→    const bar = document.getElementById('navProgress');
   953→    if (!bar) return;
   954→    let timer;
   955→    function startProgress() {
   956→        bar.classList.add('active');
   957→        bar.style.width = '0%';
   958→        let pct = 0;
   959→        clearInterval(timer);
   960→        timer = setInterval(() => {
   961→            pct += pct < 70 ? Math.random() * 8 : (pct < 90 ? Math.random() * 2 : 0);
   962→            if (pct >= 95) { clearInterval(timer); pct = 95; }
   963→            bar.style.width = pct + '%';
   964→        }, 120);
   965→    }
   966→    function finishProgress() {
   967→        clearInterval(timer);
   968→        bar.style.width = '100%';
   969→        setTimeout(() => { bar.classList.remove('active'); bar.style.width = '0%'; }, 400);
   970→    }
   971→    // Intercept sidebar nav link clicks
   972→    document.querySelectorAll('.nav-link[href]:not([href="#"])').forEach(a => {
   973→        a.addEventListener('click', function(e) {
   974→            if (!e.ctrlKey && !e.metaKey && !e.shiftKey) startProgress();
   975→        });
   976→    });
   977→    window.addEventListener('pageshow', finishProgress);
   978→    document.addEventListener('DOMContentLoaded', finishProgress);
   979→})();
   980→
   981→// ---- SKELETON → SHIMMER for placeholder spans ----
   982→document.querySelectorAll('.placeholder').forEach(el => el.classList.add('skeleton'));
